ersionId":"{{ forms.planning_console_result_filter.planVersionId }}","operationStatus":"{{ forms.planning_console_result_filter.operationStatus }}"}},"autoLoad":true},"resourcePlans":{"key":"resourcePlans","label":"资源负荷","sourceType":"custom","serviceName":"planning","serviceMethod":"getPlanningConsoleData","postData":{"dataset":"resourcePlans","filters":{"to":"{{ forms.planning_console_result_filter.to }}","from":"{{ forms.planning_console_result_filter.from }}","itemId":"{{ forms.planning_console_result_filter.itemId }}","resourceId":"{{ forms.planning_console_result_filter.resourceId }}","scenarioId":"{{ forms.planning_console_filter.scenarioId }}","operationId":"{{ forms.planning_console_result_filter.operationId }}","demandStatus":"{{ forms.planning_console_result_filter.demandStatus }}","planVersionId":"{{ forms.planning_console_result_filter.planVersionId }}","operationStatus":"{{ forms.planning_console_result_filter.operationStatus }}"}},"autoLoad":true},"operationPlans":{"key":"operationPlans","label":"计划单","sourceType":"custom","serviceName":"planning","serviceMethod":"listItems","postData":{"limit":300,"filters":{"plan_version_id":"{{ forms.planning_console_filter.version}}"},"orderBy":"reference","tableName":"planning_operationplan","orderDirection":"asc"},"autoLoad":true},"preflightIssues":{"key":"preflightIssues","label":"数据完整性预检","sourceType":"custom","serviceName":"planning","serviceMethod":"preflightSupplyPlanIssues","postData":{"jobType":"supply_plan"},"autoLoad":false}},"apis":{"planningRun":{"serviceName":"planning","serviceMethod":"runSupplyPlan","method":"POST"},"planningCancel":{"serviceName":"planning","serviceMethod":"cancelPlanningRun","method":"POST"},"planningPublish":{"serviceName":"planning","serviceMethod":"publishPlanVersion","method":"POST"},"planningPreflight":{"serviceName":"planning","serviceMethod":"preflightSupplyPlanIssues","method":"POST"}},"scriptPolicy":{"capabilities":["http.execute","form.patch","source.refresh","source.set","message.error","message.success","message.warning"]},"blocks":[{"id":"planning_console_actions","gap":6,"kind":"buttonGroup","align":"left","title":"","actions":[{"code":"preflight","icon":"ri-shield-check-line","mode":"button","type":"button","label":"数据预检","round":false,"circle":false,"script":"async function main() {\n  const filter = this.forms.planning_console_filter || {};\n  const scenarioId = String(filter.scenarioId || \"\").trim();\n  if (!scenarioId) {\n    await this.$message.warning(\"请先选择排产场景。\");\n    return false;\n  }\n  const overrides = {\n    currentdate: String(filter.currentDate || \"now\").trim() || \"now\",\n    \"plan.solver\": String(filter.solver || \"heuristic\").trim() || \"heuristic\",\n    constraints: Number(filter.constraints ?? 52),\n    \"plan.iterationmax\": Number(filter.iterationMax ?? 0),\n    \"plan.resourceiterationmax\": Number(filter.resourceIterationMax ?? 500),\n    \"plan.rotateResources\": filter.rotateResources !== false,\n    \"plan.individualPoolResources\": filter.individualPoolResources === true,\n  };\n  const issues = await this.executeHttp({\n    api: \"planningPreflight\",\n    method: \"POST\",\n    body: { jobType: \"supply_plan\", scenarioId, overrides },\n  });\n  await this.$source.set(\"preflightIssues\", issues);\n  const rows = Array.isArray(issues) ? issues : [];\n  const errorCount = rows.filter((issue) => issue && issue.severity === \"error\").length;\n  const warningCount = rows.filter((issue) => issue && issue.severity === \"warning\").length;\n  if (errorCount > 0) {\n    await this.$message.warning(\"预检完成，发现 \" + errorCount + \" 项错误和 \" + warningCount + \" 项警告。\");\n  } else {\n    await this.$message.success(\"数据完整性预检通过。\");\n  }\n  return issues;\n}","disabled":false,"showDropdownIcon":true},{"code":"run","icon":"ri-play-circle-line","mode":"button","type":"button","label":"开始排产","round":false,"circle":false,"script":"async function main() {\n  debugger\n  const filter = this.forms.planning_console_filter || {};\n  const scenarioId = String(filter.scenarioId || \"\").trim();\n  const valid = await this.executeAction({\n  node: \"planning_console_filter\",\n  method: \"validate\",\n});\nif(valid==false){\n  throw new Error(''表单校验失败'');\n}\n  const overrides = {\n    currentdate: String(filter.currentDate || \"now\").trim() || \"now\",\n    \"plan.solver\": String(filter.solver || \"heuristic\").trim() || \"heuristic\",\n    constraints: Number(filter.constraints ?? 52),\n    \"plan.iterationmax\": Number(filter.iterationMax ?? 0),\n    \"plan.resourceiterationmax\": Number(filter.resourceIterationMax ?? 500),\n    \"plan.rotateResources\": filter.rotateResources !== false,\n    \"plan.individualPoolResources\": filter.individualPoolResources === true,\n  };\n\n  const capabilities = this.data.runtimeCapabilities || {};\n  const engine = capabilities.engine || {};\n  const trigger = capabilities.trigger || {};\n  const worker = capabilities.worker || {};\n  // if (capabilities.canManage !== true) {\n  //   await this.$message.error(\"当前用户没有启动排产的权限。\");\n  //   return false;\n  // }\n  // if (engine.available !== true) {\n  //   await this.$message.warning(\"排产引擎当前不可用，请检查 frePPLe 运行配置。\");\n  //   return false;\n  // }\n  // if (trigger.configured !== true) {\n  //   await this.$message.warning(\"后台任务服务当前不可用，请先完成运行配置。\");\n  //   return false;\n  // }\n  // if (worker.online !== true) {\n  //   await this.$message.warning(worker.online === false\n  //     ? \"Trigger.dev Worker 当前离线，请先启动排产后台任务。\"\n  //     : \"无法确认 Trigger.dev Worker 在线状态，请检查后台任务服务。\");\n  //   return false;\n  // }\n\n  const result = await this.executeHttp({\n    api: \"planningRun\",\n    method: \"POST\",\n    body: {\n      jobType: \"supply_plan\",\n      scenarioId,\n      name: String(filter.runName || \"\").trim() || \"控制台排产运行\",\n      overrides,\n    },\n  });\n  await this.$source.set(\"planningRunStarted\", result);\n  await this.$source.refresh(\"summary\");\n  await this.$source.refresh(\"runs\");\n  await this.$source.refresh(\"versionOptions\");\n  const versionId = result && result.version && result.version.id ? String(result.version.id) : \"\";\n  if (versionId) {\n    await this.$form.patch(\"planning_console_result_filter\", { planVersionId: versionId });\n    await this.$source.refresh(\"summary\");\n    await this.$source.refresh(\"demands\");\n    await this.$source.refresh(\"operationPlans\");\n    await this.$source.refresh(\"materials\");\n    await this.$source.refresh(\"planResources\");\n    await this.$source.refresh(\"resourcePlans\");\n    await this.$source.refresh(\"problems\");\n    await this.$source.refresh(\"constraints\");\n    await this.$source.refresh(\"flow\");\n    await this.$source.refresh(\"bom\");\n  }\n  await this.$message.success(\"排产任务已提交。\");\n  return result;\n}","status":"primary","disabled":false,"showDropdownIcon":true},{"code":"cancel","icon":"ri-stop-circle-line","mode":"button","type":"button","label":"取消运行","round":false,"circle":false,"script":"async function main() {\n  const grid = this.grids.planning_console_runs_grid || {};\n  const run = grid.currentRow || null;\n  if (!run || !run.id) {\n    await this.$message.warning(\"请先在运行记录中选择一条任务。\");\n    return false;\n  }\n  if (![\"queued\", \"running\"].includes(String(run.status || \"\"))) {\n    await this.$message.warning(\"仅排队中或运行中的任务可以取消。\");\n    return false;\n  }\n\n  const result = await this.executeHttp({\n    api: \"planningCancel\",\n    method: \"POST\",\n    body: { runId: run.id },\n  });\n  await this.$source.set(\"planningRunCanceled\", result);\n  await this.$source.refresh(\"summary\");\n  await this.$source.refresh(\"runs\");\n  await this.$source.refresh(\"versionOptions\");\n  await this.$message.success(\"取消请求已提交。\");\n  return result;\n}","status":"danger","disabled":false,"showDropdownIcon":true},{"code":"publish","icon":"ri-send-plane-line","mode":"button","type":"button","label":"发布版本","round":false,"circle":false,"script":"async function main() {\n  const filter = this.forms.planning_console_result_filter || {};\n  const options = Array.isArray(this.data.versionOptions) ? this.data.versionOptions : [];\n  const versionId = String(\n    filter.planVersionId || options.find((option) => option && option.is_current)?.id || \"\"\n  ).trim();\n  if (!versionId) {\n    await this.$message.warning(\"当前没有可发布的计划版本。\");\n    return false;\n  }\n\n  const selected = options.find((option) => option && option.id === versionId);\n  const versionStatus = String((selected && selected.status) || \"\");\n  if (versionStatus !== \"completed\") {\n    await this.$message.warning(\"仅已完成的计划版本可以发布。\");\n    return false;\n  }\n\n  const result = await this.executeHttp({\n    api: \"planningPublish\",\n    method: \"POST\",\n    body: { id: versionId },\n  });\n  await this.$source.set(\"planningVersionPublished\", result);\n  await this.$source.refresh(\"summary\");\n  await this.$source.refresh(\"demands\");\n  await this.$source.refresh(\"operationPlans\");\n  await this.$source.refresh(\"materials\");\n  await this.$source.refresh(\"planResources\");\n  await this.$source.refresh(\"resourcePlans\");\n  await this.$source.refresh(\"problems\");\n  await this.$source.refresh(\"constraints\");\n  await this.$source.refresh(\"runs\");\n  await this.$source.refresh(\"flow\");\n  await this.$source.refresh(\"bom\");\n  await this.$source.refresh(\"versionOptions\");\n  await this.$message.success(\"计划版本已发布。\");\n  return result;\n}","disabled":false,"showDropdownIcon":true},{"code":"refresh","icon":"ri-refresh-line","mode":"button","type":"button","label":"刷新","round":false,"circle":false,"disabled":false,"directives":[{"type":"refreshDataSources","sourceKeys":["summary","demands","operationPlans","materials","planResources","resourcePlans","problems","constraints","runs","flow","bom","versionOptions","runtimeCapabilities"]}],"showDropdownIcon":true},{"code":"pData","type":"button","label":"测试","